class Solution {
public:
    int removeOnes(vector<vector<int>>& grid) {
        int rows = grid.size(), cols = grid[0].size();
        int initial = 0;
        for (int r = 0; r < rows; ++r) {
            for (int c = 0; c < cols; ++c) {
                if (grid[r][c]) initial |= 1 << (r * cols + c);
            }
        }
        queue<int> q;
        unordered_set<int> seen;
        q.push(initial);
        seen.insert(initial);
        int steps = 0;
        while (!q.empty()) {
            int count = q.size();
            while (count--) {
                int mask = q.front();
                q.pop();
                if (mask == 0) return steps;
                for (int r = 0; r < rows; ++r) {
                    for (int c = 0; c < cols; ++c) {
                        if (!(mask & (1 << (r * cols + c)))) continue;
                        int next = mask;
                        for (int j = 0; j < cols; ++j) next &= ~(1 << (r * cols + j));
                        for (int i = 0; i < rows; ++i) next &= ~(1 << (i * cols + c));
                        if (seen.insert(next).second) q.push(next);
                    }
                }
            }
            ++steps;
        }
        return -1;
    }
};
